// @ts-ignore .open-next/worker.js is generated by the OpenNext build
import handler from "./.open-next/worker.js";

async function expireAuthorApplications(env: any) {
  const db = env.DB as D1Database;
  if (!db) return;
  for (const statement of [
    "ALTER TABLE author_applications ADD COLUMN approved_at TEXT",
    "ALTER TABLE author_applications ADD COLUMN payment_deadline TEXT",
    "ALTER TABLE author_applications ADD COLUMN payment_order_id TEXT",
    "ALTER TABLE author_applications ADD COLUMN payment_id TEXT",
    "ALTER TABLE author_applications ADD COLUMN payment_currency TEXT",
    "ALTER TABLE author_applications ADD COLUMN payment_amount REAL"
  ]) { try { await db.prepare(statement).run(); } catch {} }
  try {
    await db.prepare("UPDATE author_applications SET payment_deadline=datetime(approved_at, '+3 days') WHERE status='approved_payment_pending' AND approved_at IS NOT NULL AND payment_deadline IS NOT NULL AND julianday(payment_deadline) < julianday(approved_at, '+3 days') - (1.0/86400.0)").run();
  } catch {}

  const { results = [] } = await db.prepare(
    "SELECT id,full_name,email FROM author_applications WHERE status='approved_payment_pending' AND payment_deadline IS NOT NULL AND payment_deadline <= ?"
  ).bind(new Date().toISOString()).all<any>();

  const resendKey = String(env.RESEND_API_KEY || "");
  for (const application of results) {
    const updated = await db.prepare(
      "DELETE FROM author_applications WHERE id=? AND status='approved_payment_pending' AND payment_deadline IS NOT NULL AND payment_deadline <= ?"
    ).bind(application.id, new Date().toISOString()).run();

    if (updated.meta?.changes && resendKey) {
      try {
        const { Resend } = await import("resend");
        const resend = new Resend(resendKey);
        const safeName = String(application.full_name || "Author").replace(/</g, "&lt;").replace(/>/g, "&gt;");
        await resend.emails.send({
          from: "no-reply@shoppersocean.com",
          to: application.email,
          subject: "Shoppers Ocean Author Registration",
          html: `<div style="font-family:Arial,sans-serif;line-height:1.7;color:#1e293b;">
            <p>Dear ${safeName},</p>
            <p>Sorry! Your author registration payment was not completed within the required three-day period. As a result, your registration as an author could not be completed.</p>
            <p>You may contact Shoppers Ocean if you wish to enquire about registering again.</p>
            <p>Regards,<br/>Shoppers Ocean</p>
          </div>`,
        });
      } catch (error) {
        console.error("Author expiry email failed:", error);
      }
    }
  }
}

async function expireAdminNotifications(env: any) {
  const db = env.DB as D1Database;
  if (!db) return;
  const cutoff = new Date(Date.now() - 24 * 60 * 60 * 1000).toISOString();
  try {
    await db.prepare("DELETE FROM admin_notifications WHERE created_at <= ?").bind(cutoff).run();
  } catch (error) {
    // The notifications table may not exist until the first notification is created.
    console.error("Admin notification cleanup failed:", error);
  }
}

export default {
  fetch: handler.fetch,
  async scheduled(_controller: ScheduledController, env: any, ctx: ExecutionContext) {
    ctx.waitUntil(Promise.all([
      expireAuthorApplications(env),
      expireAdminNotifications(env)
    ]));
  },
};
